import{z as E,x as A,o as c,c as i,q as s,j as t,D as a,d as r,s as d,S as l,b as o}from"./chunks/framework.C8m1ZpeB.js";const M=JSON.parse('{"title":"内存序指令 fence","description":"","frontmatter":{"title":"内存序指令 fence","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fence-instructions.md","filePath":"cs/fence-instructions.md","lastUpdated":1791063341000}'),f={name:"cs/fence-instructions.md"};function B(p,e,h,m,u,D){const n=A("Mermaid");return c(),i("div",null,[e[2]||(e[2]=s('<h1 id="内存序指令-fence" tabindex="-1">内存序指令 fence <a class="header-anchor" href="#内存序指令-fence" aria-label="Permalink to &quot;内存序指令 fence&quot;">​</a></h1><div class="epigraph"><p>弱序机器上，store 后面的 load 可以先执行；fence 告诉硬件哪些程序序必须变成对其他核可见的序，原子指令的 acquire/release 是它的特化。</p><footer>—— 据 The RISC-V Instruction Set Manual；ARM ARM；Intel SDM；Adve and Gharachorloo, Shared Memory Consistency Models, IEEE Computer 1996 整理</footer></div><p><a href="/cs/lr-sc-cas">上一课</a>给出 RMW。<a href="/cs/dma-scatter-gather">DMA</a> 要求描述符写对设备可见。<a href="/cs/nvm-persistent">持久内存</a> 还要冲刷。缺口是 CPU 之间的 <strong>内存一致性模型与 fence</strong>：x86 近似 TSO，ARM/RISC-V 更弱。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>乱序核与写缓冲让独立地址的访问重排。若核0 store 数据再 store 就绪标志，核1 load 标志再 load 数据，弱序上可能看见新标志旧数据。fence（RISC-V <code>fence</code>，ARM <code>dmb</code>/<code>dsb</code>，x86 <code>mfence</code>/<code>sfence</code>/<code>lfence</code> 及 <code>lock</code> 副作用）切开。缺口不是 CAS 循环写法，而是<strong>哪些重排被禁止</strong>。</p><p>TSO（x86）：允许 store-load 重排为主，程序员少插 fence；仍要 <code>mfence</code> 于少数模式。ARM/RV：要显式 acquire/release 或 fence。C/C++ 的 <code>memory_order</code> 降到这些指令。</p><p><span class="marginnote">术语翻译：TSO 可以记成「只许一处插队」的顺序模型——store 后面的 load 允许提前，其余顺序都保持程序序。所以 x86 程序大多数时候不用插 fence，只有「写完立刻读、且不能读到自己的写」这类少见模式才需要 <code>mfence</code>；ARM/RISC-V 则处处弱序，配对要自己钉。</span></p><h3 id="fence-不是「刷新-cache」" tabindex="-1">fence 不是「刷新 cache」 <a class="header-anchor" href="#fence-不是「刷新-cache」" aria-label="Permalink to &quot;fence 不是「刷新 cache」&quot;">​</a></h3><p>它不把缓存丢掉，而是约束提交与可见性序。<code>clflush</code> 才冲缓存行（持久与 DMA 有时要）。把 <code>fence</code> 当 <code>wbinvd</code>，性能与语义都错。设备 MMIO 往往需要更强的 I/O 围栏，以防写缓冲合并门铃。</p><p><span class="marginnote">Adve/Gharachorloo 1996 是模型综述。RISC-V 手册第 14 章一类（版本因手册而变）描述 fence 前趋。ARM ARM 的 barrier。Intel SDM 的 MFENCE。本课不发明论文号。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>生产者：写 payload，<code>release</code> store 或 <code>fence rw,w</code> 再写 flag。消费者：读 flag，<code>acquire</code> 或 <code>fence r,rw</code> 再读 payload。RISC-V <code>fence.i</code> 管指令缓存，是另一条（自修改代码）。PCIe DMA：写描述符后可能要 store-release 再写门铃 MMIO。</p>',12)),(c(),t(l,null,{default:a(()=>[d(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ST%5B%22store%20%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20REL%5B%22release%20%2F%20fence%22%5D%0A%20%20REL%20--%3E%20FG%5B%22store%20%E6%A0%87%E5%BF%97%22%5D%0A%20%20FG%20--%3E%20ACQ%5B%22acquire%20%2F%20fence%22%5D%0A%20%20ACQ%20--%3E%20LD%5B%22load%20%E6%95%B0%E6%8D%AE%22%5D%0A%20%20LD%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9ASIMD%20%E4%B8%8D%E6%94%B9%E5%8F%98%E8%BF%99%E5%A5%97%E5%BA%8F%E7%9A%84%E5%AF%B9%E8%B1%A1%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=o("p",null,"与单核：编译器重排也要编译器屏障；本课偏硬件指令。",-1)),e[4]||(e[4]=o("h2",{id:"机制",tabindex:"-1"},[r("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[5]||(e[5]=o("p",null,"下一课 SIMD 并行的是数据通路，内存序仍按标量模型作用于每条向量访存（实现可更宽）。RVV 的向量 load 同样受 fence 约束。本课把 ISA 对照从「运算」接到「多核可见性」。",-1)),(c(),t(l,null,{default:a(()=>[d(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E6%A0%B80%20%E8%AE%A1%E5%88%92%3A%20%E5%85%88%20store%20%E6%95%B0%E6%8D%AE%2C%20%E5%86%8D%20store%20%E6%A0%87%E5%BF%97%22%5D%20--%3E%20W%5B%22%E5%86%99%E7%BC%93%E5%86%B2%E4%B8%8E%E4%B9%B1%E5%BA%8F%E6%8A%8A%E4%B8%A4%E6%AC%A1%20store%20%E4%BA%A4%E6%8D%A2%22%5D%0A%20%20W%20--%3E%20V%5B%22%E6%A0%B81%20%E5%85%88%E7%9C%8B%E8%A7%81%E6%96%B0%E6%A0%87%E5%BF%97%22%5D%0A%20%20V%20--%3E%20L%5B%22%E6%A0%B81%20%E8%BD%AC%E5%A4%B4%E5%8E%BB%E8%AF%BB%E6%95%B0%E6%8D%AE%2C%20%E5%8F%AA%E6%8B%BF%E5%88%B0%E6%97%A7%E5%80%BC%22%5D%0A%20%20L%20--%3E%20BUG%5B%22%E5%8D%8F%E8%AE%AE%E8%BF%9D%E7%BA%A6%3A%20%E4%B8%8D%E6%98%AF%E9%80%BB%E8%BE%91%E5%86%99%E9%94%99%2C%20%E6%98%AF%E5%BA%8F%E8%A2%AB%E9%87%8D%E6%8E%92%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=s('<p><span class="marginnote">直觉类比：release 像交卷前把所有草稿都订正完才举手示意「我写完了」，acquire 像看见「写完了」的牌子才允许走进去看卷子。两者配对，观察者永远看不到「举了手但卷子还没订正」的中间态；裸 store 标志缺的就是这道订正步骤。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 C++ 标准逐条背完，不证明 RCpc vs RCsc。不写 GPU 的 <code>__threadfence</code>。不进入 JVM 内存模型全书。</p><p>后课默认：弱序 ISA 用 fence/acquire-release 配对生产者消费者；x86 TSO 更强但仍非顺序一致。下一课 SIMD 扩展。</p><p><span class="marginnote">常见误区：初学者容易把 fence 当成「把缓存刷回内存」。实际上 fence 只约束指令提交与可见的先后，不碰任何缓存行；脏行什么时候写回由缓存一致性协议说了算。真正冲缓存的是 <code>clflush</code> 一类指令，语义与性能都和 fence 是两回事。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>弱序允许重排；fence 切开可见性。</li><li>不是冲缓存；DMA/MMIO 常需更强序。</li><li>x86 TSO vs ARM/RV 弱序决定 fence 密度。</li><li>出处：RISC-V ISA；ARM ARM；Intel SDM；Adve and Gharachorloo, 1996。</li></ul>',7))])}const S=E(f,[["render",B]]);export{M as __pageData,S as default};
